.apprsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1f3326;
    background: linear-gradient(160deg, #f1f7ee 0%, #e7f1e4 100%);
    border-radius: 18px;
}

.apprsim-container * {
    box-sizing: border-box;
}

.apprsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #234d2e 0%, #2f7d44 55%, #6cae5f 100%);
    color: #f3fbf0;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(35, 77, 46, 0.30);
}

.apprsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.apprsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #cdeec2;
    background: rgba(255, 255, 255, 0.12);
    padding: 5px 14px;
    border-radius: 999px;
}

.apprsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e4f4dd;
}

.apprsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2a5634;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.apprsim-period-counter #currentDay,
.apprsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #234d2e;
}

.apprsim-round-name {
    background: #d6ecca;
    color: #234d2e;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.apprsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a5a16;
    background: #f6e6cf;
    padding: 4px 12px;
    border-radius: 999px;
}

.apprsim-interventions {
    font-size: 0.82rem;
    font-weight: 700;
    color: #2f5d8a;
    background: #dde9f4;
    padding: 4px 12px;
    border-radius: 999px;
}

.apprsim-interventions.apprsim-int-over {
    color: #ffffff;
    background: #c0392b;
}

.apprsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.apprsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #d6e6cd;
    box-shadow: 0 4px 14px rgba(35, 77, 46, 0.06);
    border-top: 4px solid #6cae5f;
}

.apprsim-card-engagement { border-top-color: #2f7d44; }
.apprsim-card-generativity { border-top-color: #d49a1f; }
.apprsim-card-impact { border-top-color: #2f6f7d; }
.apprsim-card-adoption { border-top-color: #7a5bb0; }

.apprsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #5e7a64;
}

.apprsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #234d2e;
}

.apprsim-card-engagement .apprsim-value { color: #2f7d44; }
.apprsim-card-generativity .apprsim-value { color: #b9820f; }
.apprsim-card-impact .apprsim-value { color: #2f6f7d; }
.apprsim-card-adoption .apprsim-value { color: #7a5bb0; }

.apprsim-sublabel {
    font-size: 0.76rem;
    color: #6f8a74;
    line-height: 1.35;
}

.apprsim-engagement-fail .apprsim-value { color: #c0392b; }
.apprsim-engagement-target .apprsim-value { color: #2f7d44; }

.apprsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #234d2e;
    color: #eef8e9;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.apprsim-budget-bar.apprsim-budget-over {
    background: #8c2f23;
}

.apprsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.apprsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #2f7d44;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(35, 77, 46, 0.05);
}

.apprsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.apprsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #234d2e;
    margin-bottom: 6px;
}

.apprsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #344f3a;
}

.apprsim-briefing-text strong { color: #2f7d44; }
.apprsim-briefing-text em { color: #9a5a16; font-style: italic; }

.apprsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d6e6cd;
    box-shadow: 0 4px 14px rgba(35, 77, 46, 0.06);
}

.apprsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #234d2e;
    border-bottom: 2px solid #e2efdb;
    padding-bottom: 8px;
}

.apprsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2a4730;
    margin: 14px 0 6px;
}

.apprsim-container select,
.apprsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #bcd6b0;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f6fbf3;
    color: #1f3326;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.apprsim-container select:focus,
.apprsim-container input[type="number"]:focus {
    outline: none;
    border-color: #2f7d44;
    box-shadow: 0 0 0 3px rgba(47, 125, 68, 0.15);
}

.apprsim-container select option {
    background-color: #ffffff;
    color: #1f3326;
}

.apprsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2f7d44;
}

.apprsim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2a5634;
    margin-top: 4px;
}

.apprsim-range-readout span:last-child {
    color: #2f7d44;
    font-weight: 800;
}

.apprsim-hint {
    font-size: 0.8rem;
    color: #6f8a74;
    margin-top: 4px;
    line-height: 1.4;
}

.apprsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.apprsim-container .btn-primary {
    background: linear-gradient(135deg, #2f7d44 0%, #6cae5f 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(47, 125, 68, 0.28);
}

.apprsim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.apprsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #bcd6b0;
    color: #5e7a64;
}

.apprsim-coach {
    background: #234d2e;
    color: #eef8e9;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(35, 77, 46, 0.22);
}

.apprsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #a8d79a;
    margin-bottom: 8px;
}

.apprsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.apprsim-coach-body strong { color: #f4cd7a; }
.apprsim-coach-body em { color: #f2b58a; font-style: italic; }

.apprsim-history,
.apprsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d6e6cd;
    box-shadow: 0 4px 14px rgba(35, 77, 46, 0.06);
}

.apprsim-history h3,
.apprsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #234d2e;
}

.apprsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #2a4730;
}

.apprsim-container table#usfHistoryTable th {
    background: #e8f2e2;
    color: #234d2e;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d2e6c8;
}

.apprsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef5ea;
}

.apprsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f7fbf4;
}

.apprsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .apprsim-container {
        padding: 14px;
    }
    .apprsim-header h1 {
        font-size: 1.7rem;
    }
    .apprsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .apprsim-value {
        font-size: 2rem;
    }
    .apprsim-clock {
        margin-left: 0;
    }
    .apprsim-period-counter {
        font-size: 0.88rem;
    }
    .apprsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .apprsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 completion debrief (append-only, self-contained) ===== */
.apprsim-cm { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #1f3326; text-align: center; padding: 4px 2px 8px; }
.apprsim-cm-title { font-size: 20px; font-weight: 700; color: #234d2e; margin-bottom: 14px; }
.apprsim-cm-scorewrap { background: linear-gradient(135deg, #234d2e 0%, #2f7d44 55%, #6cae5f 100%); color: #f3fbf0; border-radius: 14px; padding: 18px 16px; margin: 0 auto 16px; max-width: 420px; }
.apprsim-cm-score { font-size: 46px; font-weight: 800; line-height: 1; }
.apprsim-cm-score-max { font-size: 20px; font-weight: 600; opacity: 0.85; }
.apprsim-cm-grade { font-size: 18px; font-weight: 700; margin-top: 8px; }
.apprsim-cm-badges { margin-top: 10px; }
.apprsim-cm-badge { display: inline-block; font-size: 12px; font-weight: 700; padding: 4px 12px; border-radius: 999px; letter-spacing: .2px; }
.apprsim-cm-badge-ok { background: #d6ecca; color: #234d2e; }
.apprsim-cm-badge-miss { background: #f6e6cf; color: #9a5a16; }
.apprsim-cm-kpis { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin: 0 auto 14px; max-width: 470px; }
.apprsim-cm-kpi { flex: 1 1 95px; min-width: 95px; background: #eef5ea; border: 1px solid #d6ecca; border-radius: 10px; padding: 10px 6px; }
.apprsim-cm-kpi-val { font-size: 22px; font-weight: 700; color: #2a5634; }
.apprsim-cm-kpi-lbl { font-size: 11px; font-weight: 600; color: #4a6b52; text-transform: uppercase; letter-spacing: .3px; margin-top: 2px; }
.apprsim-cm-insights { text-align: left; max-width: 520px; margin: 0 auto; background: #f7fbf4; border-left: 4px solid #2f7d44; border-radius: 8px; padding: 12px 16px; }
.apprsim-cm-ins-h { font-weight: 700; color: #234d2e; margin-bottom: 6px; font-size: 14px; }
.apprsim-cm-insights ul { margin: 0; padding-left: 18px; }
.apprsim-cm-insights li { font-size: 13px; line-height: 1.5; margin-bottom: 6px; color: #2c3b30; }
@media (max-width: 480px) { .apprsim-cm-kpi { flex-basis: 40%; } .apprsim-cm-score { font-size: 38px; } .apprsim-cm-scorewrap { max-width: 100%; } }

