(function() {
    'use strict';

    class AppreciativeAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Appreciative Change`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card.
            this.START_ENGAGEMENT = 41;     // change-engagement pulse, falling
            this.START_GENERATIVITY = 12;   // little energy after three failed programs
            this.START_IMPACT = 10;         // adopted progress to 2030 targets
            this.START_ADOPTION = 25;       // shop-floor uptake below 30%
            this.TARGET_ENGAGEMENT = 60;    // restart target
            this.TARGET_GEN = 55;
            this.TARGET_IMPACT = 55;
            this.TARGET_ADOPTION = 55;
            this.INTERVENTION_CAP = 3;      // absorptive-limit constraint
            this.INTERVENTION_COST = 800;   // EUR 0.8M per org-wide intervention, in thousands
            this.BUDGET_CAP = 6000;         // EUR 6.0M change budget, in thousands

            // Concept truths.
            this.TRUE_FRAME = `appreciative`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    engagement: this.START_ENGAGEMENT,
                    generativity: this.START_GENERATIVITY,
                    impact: this.START_IMPACT,
                    adoption: this.START_ADOPTION,
                    interventionsUsed: 0,
                    budgetUsed: 0,
                    overEngaged: false,
                    tokenism: false,
                    targetMissed: false,
                    engagementHistory: [this.START_ENGAGEMENT],
                    generativityHistory: [this.START_GENERATIVITY],
                    adoptionHistory: [this.START_ADOPTION],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seed a neutral / middling mix — NOT the textbook-correct play.
                state.decisions = {
                    frame: `hybrid`,
                    core: `onesite`,
                    candor: 50,
                    arc: `discovery`,
                    participants: `narrow`,
                    pacing: `spread`,
                    intCount: 1,
                    ownership: `mixed`,
                    selection: `safe`,
                    extraEvents: 0,
                    capacity: 50,
                    cadence: `quarterly`,
                    proof: `lagging`,
                    pitch: `rebrand`,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const frame = document.getElementById(`frameInput`);
                const core = document.getElementById(`coreInput`);
                const candor = document.getElementById(`candorInput`);
                if (frame) decisions.frame = frame.value;
                if (core) decisions.core = core.value;
                if (candor) decisions.candor = parseInt(candor.value, 10);
                if (!Number.isFinite(decisions.candor) || decisions.candor < 0 || decisions.candor > 100) {
                    warn(`warn_candor_range`); return false;
                }
            } else if (round === 2) {
                const arc = document.getElementById(`arcInput`);
                const part = document.getElementById(`participantsInput`);
                const pace = document.getElementById(`pacingInput`);
                const intc = document.getElementById(`intCountInput`);
                if (arc) decisions.arc = arc.value;
                if (part) decisions.participants = part.value;
                if (pace) decisions.pacing = pace.value;
                if (intc) decisions.intCount = parseInt(intc.value, 10);
                if (!Number.isFinite(decisions.intCount) || decisions.intCount < 0 || decisions.intCount > this.INTERVENTION_CAP) {
                    warn(`warn_intcount_range`); return false;
                }
            } else if (round === 3) {
                const own = document.getElementById(`ownershipInput`);
                const sel = document.getElementById(`selectionInput`);
                const extra = document.getElementById(`extraEventsInput`);
                const cap = document.getElementById(`capacityInput`);
                if (own) decisions.ownership = own.value;
                if (sel) decisions.selection = sel.value;
                if (extra) decisions.extraEvents = parseInt(extra.value, 10);
                if (cap) decisions.capacity = parseInt(cap.value, 10);
                if (!Number.isFinite(decisions.extraEvents) || decisions.extraEvents < 0 || decisions.extraEvents > 2) {
                    warn(`warn_extra_range`); return false;
                }
                if (!Number.isFinite(decisions.capacity) || decisions.capacity < 0 || decisions.capacity > 100) {
                    warn(`warn_capacity_range`); return false;
                }
            } else if (round === 4) {
                const cad = document.getElementById(`cadenceInput`);
                const proof = document.getElementById(`proofInput`);
                const pitch = document.getElementById(`pitchInput`);
                const conv = document.getElementById(`convictionInput`);
                if (cad) decisions.cadence = cad.value;
                if (proof) decisions.proof = proof.value;
                if (pitch) decisions.pitch = pitch.value;
                if (conv) decisions.conviction = parseInt(conv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas: engagement = pulse on change; generativity = energy / new possibilities;
            // adoption = shop-floor uptake; impactBase = direct progress; paper = compliance
            // without belief; spend = budget; interventions consumed against the cap.
            let engDelta = 0, genDelta = 0, adoptDelta = 0, impactBase = 0, paper = 0;
            let spend = 0, interventions = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                spend += 300; // diagnostic + positive-core mapping, EUR 0.3M

                // Inquiry frame — the central choice (Common Error 1: the deficit reflex).
                switch (d.frame) {
                    case `appreciative`: engDelta += 10; genDelta += 12; adoptDelta += 5; coachKey = `coach_r1_appreciative`; break;
                    case `hybrid`: engDelta += 3; genDelta += 4; adoptDelta += 1; coachKey = `coach_r1_hybrid`; break;
                    case `deficit`: engDelta -= 8; genDelta -= 6; adoptDelta -= 5; coachKey = `coach_r1_deficit`; break;
                    case `repeat`: engDelta -= 12; genDelta -= 10; adoptDelta -= 8; coachKey = `coach_r1_repeat`; break;
                }

                // Map the positive core — seeds the generative restart.
                switch (d.core) {
                    case `multiseed`: genDelta += 7; impactBase += 6; adoptDelta += 5; if (d.frame === this.TRUE_FRAME) coachKey = `coach_r1_strong`; break;
                    case `onesite`: genDelta += 3; impactBase += 2; adoptDelta += 2; break;
                    case `none`: genDelta -= 6; impactBase -= 2; adoptDelta -= 3; coachKey = `coach_r1_nocore`; break;
                }

                // Candor: naming this as a method failure rather than a target/motivation failure.
                if (d.candor >= 60) { genDelta += 4; engDelta += 2; }
                else if (d.candor <= 25) { genDelta -= 5; engDelta -= 3; coachKey = `coach_r1_lowcandor`; }

                summaryKey = (d.frame === this.TRUE_FRAME && d.core === `multiseed`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                interventions += d.intCount;
                spend += d.intCount * this.INTERVENTION_COST;

                // The appreciative-inquiry 4-D arc.
                switch (d.arc) {
                    case `full`: engDelta += 6; genDelta += 9; adoptDelta += 5; spend += 300; coachKey = `coach_r2_full`; break;
                    case `discovery`: engDelta += 4; genDelta += 5; adoptDelta += 2; coachKey = `coach_r2_discovery`; break;
                    case `dream`: engDelta += 5; genDelta += 4; adoptDelta -= 3; paper += 4; coachKey = `coach_r2_dream`; break;
                }

                // Who is in the room — broad co-design transfers ownership (vs tokenism).
                switch (d.participants) {
                    case `broad`: engDelta += 8; genDelta += 6; adoptDelta += 8; if (d.arc === `full`) coachKey = `coach_r2_broad`; break;
                    case `narrow`: engDelta -= 4; adoptDelta -= 4; paper += 5; coachKey = `coach_r2_narrow`; break;
                    case `token`: engDelta -= 8; genDelta -= 6; adoptDelta -= 8; paper += 6; coachKey = `coach_r2_token`; break;
                }

                // Pacing — respect the absorptive limit (Common Error 2: over-engaging).
                if (d.pacing === `spread`) { engDelta += 6; genDelta += 3; }
                else { engDelta -= 12; genDelta -= 6; ds.overEngaged = true; coachKey = `coach_r2_burst`; }

                if (d.intCount === 0) { genDelta -= 6; adoptDelta -= 4; coachKey = `coach_r2_nointervention`; }

                summaryKey = (d.arc === `full` && d.participants === `broad` && d.pacing === `spread`) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Ownership transfer (Common Error 3: tokenism).
                switch (d.ownership) {
                    case `cocreated`: adoptDelta += 10; genDelta += 6; engDelta += 3; coachKey = `coach_r3_cocreated`; break;
                    case `mixed`: adoptDelta += 4; genDelta += 2; break;
                    case `topdown`: adoptDelta -= 10; genDelta -= 8; paper += 8; ds.tokenism = true; coachKey = `coach_r3_topdown`; break;
                }

                // Selecting initiatives by adopted impact (Common Error 4: theoretical impact).
                switch (d.selection) {
                    case `adopted`: impactBase += 16; adoptDelta += 6; if (d.ownership === `cocreated`) coachKey = `coach_r3_adopted`; break;
                    case `maxpaper`: impactBase += 6; adoptDelta -= 8; paper += 6; coachKey = `coach_r3_maxpaper`; break;
                    case `safe`: impactBase += 4; adoptDelta += 2; coachKey = `coach_r3_safe`; break;
                }

                // Extra momentum events cost budget AND interventions against the cap.
                interventions += d.extraEvents;
                spend += d.extraEvents * this.INTERVENTION_COST;
                if (d.extraEvents > 0) { genDelta += d.extraEvents * 2; }

                // Respecting the absorptive limit.
                if (d.capacity >= 60) { engDelta += 5; adoptDelta += 4; }
                else if (d.capacity <= 25) { engDelta -= 8; adoptDelta -= 6; coachKey = `coach_r3_nocapacity`; }

                summaryKey = (d.ownership === `cocreated` && d.selection === `adopted`) ? `sum_r3_good` : (d.ownership === `topdown` || d.selection === `maxpaper` ? `sum_r3_paper` : `sum_r3_weak`);
            } else if (round === 4) {
                // Cadence — sustaining generativity over time (Common Error 5: event not rhythm).
                switch (d.cadence) {
                    case `rhythm`: genDelta += 10; engDelta += 4; adoptDelta += 4; coachKey = `coach_r4_rhythm`; break;
                    case `quarterly`: genDelta += 4; engDelta += 2; break;
                    case `oneoff`: genDelta -= 10; engDelta -= 4; coachKey = `coach_r4_oneoff`; break;
                }

                // Evidence of early progress.
                switch (d.proof) {
                    case `signals`: impactBase += 10; adoptDelta += 5; genDelta += 4; break;
                    case `lagging`: impactBase += 2; paper += 4; coachKey = `coach_r4_lagging`; break;
                    case `none`: impactBase -= 4; paper += 6; coachKey = `coach_r4_proofnone`; break;
                }

                // The tokenism stress-test from the CEO and works-council chair.
                switch (d.pitch) {
                    case `honest`: engDelta += 7; genDelta += 5; adoptDelta += 5; if (d.cadence === `rhythm`) coachKey = `coach_r4_honest`; break;
                    case `rebrand`: adoptDelta -= 10; genDelta -= 8; paper += 10; ds.tokenism = true; coachKey = `coach_r4_rebrand`; break;
                    case `declare`: genDelta -= 8; engDelta -= 2; paper += 8; coachKey = `coach_r4_declare`; break;
                }

                genDelta += Math.round((d.conviction - 60) / 8);

                summaryKey = (d.cadence === `rhythm` && d.proof === `signals` && d.pitch === `honest`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting.
            ds.interventionsUsed += interventions;
            ds.budgetUsed = Math.round(ds.budgetUsed + spend);

            // Over-engaging an exhausted workforce: exceeding the three-intervention cap backfires.
            const over = ds.interventionsUsed - this.INTERVENTION_CAP;
            if (over > 0) {
                engDelta -= over * 8;
                genDelta -= over * 5;
                ds.overEngaged = true;
                coachKey = `coach_over`;
            }

            // Adopted impact: impact gains are amplified by genuine adoption (impact x adoption).
            if (adoptDelta > 0) impactBase += Math.round(adoptDelta * 0.3);

            // Apply deltas.
            ds.engagement = Math.max(0, Math.min(100, ds.engagement + engDelta));
            ds.generativity = Math.max(0, Math.min(100, ds.generativity + genDelta));
            ds.adoption = Math.max(0, Math.min(100, ds.adoption + adoptDelta));

            // Impact reflects real progress minus a drag when paper compliance outruns belief.
            const impactDelta = impactBase - Math.round(paper * 0.4);
            ds.impact = Math.max(0, Math.min(100, ds.impact + impactDelta));

            // Flag tokenism / paper momentum: generativity claimed but adoption lags badly.
            if (paper >= 8 && ds.adoption < ds.generativity - 18) ds.tokenism = true;

            ds.engagementHistory.push(Math.round(ds.engagement));
            ds.generativityHistory.push(Math.round(ds.generativity));
            ds.adoptionHistory.push(Math.round(ds.adoption));

            if (round === this.ROUNDS.length) {
                if (ds.engagement < this.TARGET_ENGAGEMENT || ds.generativity < this.TARGET_GEN ||
                    ds.impact < this.TARGET_IMPACT || ds.adoption < this.TARGET_ADOPTION) {
                    ds.targetMissed = true;
                }
            }

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0: persist the composite so the instructor gradebook resolves it
            // (express_resolveDomainScore -> domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                engagement: Math.round(ds.engagement),
                engagementDelta: Math.round(engDelta),
                generativity: Math.round(ds.generativity),
                generativityDelta: Math.round(genDelta),
                impact: Math.round(ds.impact),
                impactDelta: Math.round(impactDelta),
                adoption: Math.round(ds.adoption),
                adoptionDelta: Math.round(adoptDelta),
                interventionsUsed: ds.interventionsUsed,
                budgetUsed: ds.budgetUsed,
                overEngaged: ds.overEngaged,
                tokenism: ds.tokenism,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _money(thousands) {
