        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.engagementHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                apprChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.engagementHistory },
                        { data: ds.generativityHistory },
                        { data: ds.adoptionHistory }
                    ]
                }
            };
        }

        // v1.1.0: single source of truth for the composite score. Carries the VERBATIM
        // v1.0.0 formula (equal-weighted mean of the four rounded metrics, 0-100).
        _composite(ds) {
            const e = Math.round(ds.engagement), g = Math.round(ds.generativity),
                  i = Math.round(ds.impact), a = Math.round(ds.adoption);
            return Math.round(e * 0.25 + g * 0.25 + i * 0.25 + a * 0.25);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const engagement = Math.round(ds.engagement);
            const generativity = Math.round(ds.generativity);
            const impact = Math.round(ds.impact);
            const adoption = Math.round(ds.adoption);

            const hitAll = engagement >= this.TARGET_ENGAGEMENT && generativity >= this.TARGET_GEN &&
                impact >= this.TARGET_IMPACT && adoption >= this.TARGET_ADOPTION;
            const token = ds.tokenism || (generativity >= 55 && adoption < 40);
            const composite = this._composite(ds);

            let performance = `Initiative Graveyard`, performanceKey = `grade_graveyard`;
            if (hitAll && composite >= 70) { performance = `Generative Restart`; performanceKey = `grade_generative`; }
            else if (hitAll) { performance = `Credible Restart`; performanceKey = `grade_credible`; }
            else if (generativity >= 55 && token) { performance = `Tokenistic Rebrand`; performanceKey = `grade_token`; }
            else if (engagement >= this.TARGET_ENGAGEMENT || adoption >= 45) { performance = `Energised but Incomplete`; performanceKey = `grade_energised`; }
            else if (ds.overEngaged) { performance = `Over-Engaged & Fatigued`; performanceKey = `grade_overengaged`; }

            const insights = [];
            if (hitAll) insights.push(window.mySimulation.t(`insight_generative`));
            else if (token) insights.push(window.mySimulation.t(`insight_token`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (ds.overEngaged) insights.push(window.mySimulation.t(`insight_overengaged`));
            if (adoption < 40) insights.push(window.mySimulation.t(`insight_lowadoption`));
            if (generativity < 40) insights.push(window.mySimulation.t(`insight_lowgen`));
            if (hitAll && generativity >= 65) insights.push(window.mySimulation.t(`insight_lasts`));

            return {
                engagement: engagement,
                generativity: generativity,
                impact: impact,
                adoption: adoption,
                hitAll: hitAll,
                met: hitAll,
                token: token,
                composite: composite,
                overallScore: composite,
                performance: performance,
                performanceKey: performanceKey,
                totalPeriods: history.length,
                insights: insights
            };
        }

        // v1.1.0: localized completion debrief. Without this override the engine
        // (usf-engine.js) falls back to a generic "You completed N periods" message,
        // discarding the score, grade, KPI strip and insights computed above.
        formatCompletionMessage(summary) {
            const t = (k) => (window.mySimulation ? window.mySimulation.t(k) : k);
            const s = summary || {};
            const raw = (s.composite != null) ? s.composite : (s.overallScore != null ? s.overallScore : 0);
            const score = Math.max(0, Math.min(100, Math.round(Number(raw) || 0)));
            const grade = s.performanceKey ? t(s.performanceKey) : (s.performance || '');
            const met = !!(s.met || s.hitAll);
            const badge = met
                ? `<span class="apprsim-cm-badge apprsim-cm-badge-ok">${t('cm_targets_met')}</span>`
                : `<span class="apprsim-cm-badge apprsim-cm-badge-miss">${t('cm_targets_missed')}</span>`;
            const kpi = (k, v, suf) => `<div class="apprsim-cm-kpi"><div class="apprsim-cm-kpi-val">${(v != null ? v : '—')}${suf || ''}</div><div class="apprsim-cm-kpi-lbl">${t(k)}</div></div>`;
            const ins = Array.isArray(s.insights) ? s.insights : [];
            const insHtml = ins.length
                ? `<div class="apprsim-cm-insights"><div class="apprsim-cm-ins-h">${t('cm_insights')}</div><ul>${ins.map((i) => `<li>${i}</li>`).join('')}</ul></div>`
                : '';
            return `
                <div class="apprsim-cm">
                    <div class="apprsim-cm-title">${t('cm_title')}</div>
                    <div class="apprsim-cm-scorewrap">
                        <div class="apprsim-cm-score">${score}<span class="apprsim-cm-score-max">/100</span></div>
                        <div class="apprsim-cm-grade">${grade}</div>
                        <div class="apprsim-cm-badges">${badge}</div>
                    </div>
                    <div class="apprsim-cm-kpis">
                        ${kpi('cm_kpi_engagement', s.engagement, '%')}
                        ${kpi('cm_kpi_generativity', s.generativity, '')}
                        ${kpi('cm_kpi_impact', s.impact, '')}
                        ${kpi('cm_kpi_adoption', s.adoption, '')}
                    </div>
                    ${insHtml}
                </div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.interventionsUsed > this.INTERVENTION_CAP) return window.mySimulation.t(`hint_over`);
            if (ds.tokenism) return window.mySimulation.t(`hint_token`);
            if (ds.adoption < 35) return window.mySimulation.t(`hint_adoption`);
            if (state.currentPeriod >= 3 && ds.generativity < 40) return window.mySimulation.t(`hint_gen`);
            if (ds.engagement >= this.TARGET_ENGAGEMENT && ds.generativity >= this.TARGET_GEN &&
                ds.adoption >= this.TARGET_ADOPTION) return window.mySimulation.t(`hint_strong`);
            return null;
        }

